<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Http\Requests\ContentRequest; use App\Models\Content; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Support\Arr; use Inertia\Inertia; use Inertia\Response;
class ContentController extends Controller { public function index(Request $r):Response{$items=Content::query()->when($r->search,fn($q,$v)=>$q->where('title','like',"%$v%"))->when($r->type,fn($q,$v)=>$q->where('type',$v))->when($r->status,fn($q,$v)=>$q->where('status',$v))->orderBy($r->get('sort','updated_at'),$r->get('direction','desc'))->paginate(15)->withQueryString();return Inertia::render('Admin/ContentIndex',['items'=>$items,'filters'=>$r->only('search','type','status')]);} public function create():Response{return Inertia::render('Admin/ContentForm');} public function store(ContentRequest $r):RedirectResponse{$data=$this->data($r);Content::create([...$data,'created_by'=>$r->user()->id,'updated_by'=>$r->user()->id]);return redirect()->route('admin.content.index')->with('success','Content created.');} public function edit(Content $content):Response{return Inertia::render('Admin/ContentForm',['item'=>$content]);} public function update(ContentRequest $r,Content $content):RedirectResponse{$content->update([...$this->data($r),'updated_by'=>$r->user()->id]);return redirect()->route('admin.content.index')->with('success','Content updated.');} public function destroy(Content $content):RedirectResponse{$content->delete();return back()->with('success','Content deleted.');} private function data(ContentRequest $r):array{$data=$r->safe()->except('featured_image');$data['is_featured']=$r->boolean('is_featured');if($r->hasFile('featured_image'))$data['featured_image']=$r->file('featured_image')->store('content','public');return $data;} }
